#include <stdio.h>
#include <stdlib.h>

#define MAXN 100000
#define LOG 20

static int parent[MAXN + 1];
static int depth[MAXN + 1];
static int up[LOG][MAXN + 1];
static int firstChild[MAXN + 1];
static int nextSibling[MAXN + 1];
static int subtreeSize[MAXN + 1];
static int heavy[MAXN + 1];
static int chainHead[MAXN + 1];
static int position[MAXN + 1];

static long long *segTree;
static int segSize;
static int n;

static int readInt(void) {
    int c = getchar_unlocked();
    while (c <= ' ' && c != EOF) c = getchar_unlocked();

    int value = 0;
    while (c > ' ') {
        value = value * 10 + (c - '0');
        c = getchar_unlocked();
    }
    return value;
}

static int lift(int v, int steps) {
    for (int j = 0; j < LOG; ++j) {
        if (steps & (1 << j)) v = up[j][v];
    }
    return v;
}

static long long rangeMin(int left, int right) {
    long long result = 0x3fffffffffffffffLL;
    left += segSize;
    right += segSize;

    while (left < right) {
        if (left & 1) {
            if (segTree[left] < result) result = segTree[left];
            ++left;
        }
        if (right & 1) {
            --right;
            if (segTree[right] < result) result = segTree[right];
        }
        left >>= 1;
        right >>= 1;
    }
    return result;
}

static long long shallowestMarkedAncestor(int v) {
    long long result = 0x3fffffffffffffffLL;

    while (chainHead[v] != chainHead[1]) {
        long long part = rangeMin(position[chainHead[v]], position[v] + 1);
        if (part < result) result = part;
        v = parent[chainHead[v]];
    }

    long long part = rangeMin(position[1], position[v] + 1);
    if (part < result) result = part;

    return result;
}

static void markNode(int v) {
    long long value = (long long)depth[v] * (n + 1LL) + v;
    int index = segSize + position[v];
    segTree[index] = value;

    for (index >>= 1; index > 0; index >>= 1) {
        segTree[index] = segTree[index << 1] < segTree[index << 1 | 1]
                             ? segTree[index << 1]
                             : segTree[index << 1 | 1];
    }
}

int main(void) {
    n = readInt();

    for (int i = 1; i <= n; ++i) firstChild[i] = -1;

    for (int i = 2; i <= n; ++i) {
        parent[i] = readInt();
        nextSibling[i] = firstChild[parent[i]];
        firstChild[parent[i]] = i;
        depth[i] = depth[parent[i]] + 1;
    }

    for (int i = 1; i <= n; ++i) {
        up[0][i] = parent[i];
    }
    for (int j = 1; j < LOG; ++j) {
        for (int i = 1; i <= n; ++i) {
            up[j][i] = up[j - 1][up[j - 1][i]];
        }
    }

    for (int i = 1; i <= n; ++i) {
        subtreeSize[i] = 1;
        heavy[i] = 0;
    }
    for (int i = n; i >= 2; --i) {
        int p = parent[i];
        subtreeSize[p] += subtreeSize[i];
        if (heavy[p] == 0 || subtreeSize[i] > subtreeSize[heavy[p]]) {
            heavy[p] = i;
        }
    }

    int *stackNode = (int *)malloc((n + 1) * sizeof(int));
    int *stackHead = (int *)malloc((n + 1) * sizeof(int));
    int top = 0, timer = 0;
    stackNode[top] = 1;
    stackHead[top++] = 1;

    while (top > 0) {
        int start = stackNode[--top];
        int h = stackHead[top];

        for (int v = start; v != 0; v = heavy[v]) {
            chainHead[v] = h;
            position[v] = timer++;

            for (int child = firstChild[v]; child != -1; child = nextSibling[child]) {
                if (child != heavy[v]) {
                    stackNode[top] = child;
                    stackHead[top++] = child;
                }
            }
        }
    }

    segSize = 1;
    while (segSize < n) segSize <<= 1;
    segTree = (long long *)malloc((size_t)(2 * segSize) * sizeof(long long));
    for (int i = 0; i < 2 * segSize; ++i) {
        segTree[i] = 0x3fffffffffffffffLL;
    }

    int q = readInt();
    while (q--) {
        int type = readInt();
        int v = readInt();

        if (type == 1) {
            int k = readInt();
            long long best = 0x3fffffffffffffffLL;

            if (parent[v] != 0) {
                best = shallowestMarkedAncestor(parent[v]);
            }

            int answer;
            if (best == 0x3fffffffffffffffLL) {
                answer = lift(v, k);
            } else {
                int marked = (int)(best % (n + 1LL));
                answer = lift(marked, k - 1);
            }

            printf("%d\n", answer);
        } else {
            long long best = 0x3fffffffffffffffLL;
            if (parent[v] != 0) {
                best = shallowestMarkedAncestor(parent[v]);
            }
            if (best == 0x3fffffffffffffffLL) {
                markNode(v);
            }
        }
    }

    free(stackNode);
    free(stackHead);
    free(segTree);
    return 0;
}
